    <Card className="board-section-card"><div className="card-heading"><div><h2 className="card-title">Movement ledger</h2><p className="card-subtitle">Latest 100 saved movements. Transfers and capital are excluded from sales and expenses.</p></div></div>
      {records.movements.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Type</th><th>From → To</th><th>Amount</th><th>Note</th><th>Status</th><th>Action</th></tr></thead><tbody>{records.movements.map(row => <tr key={row._id}><td>{formatBusinessDay(row.occurredOn, dateFormat)}</td><td>{row.kind.replaceAll("_", " ")}{row.feeUgx ? ` · fee ${fmt(row.feeUgx)}` : ""}</td><td>{row.fromAccount ? accountName(row.fromAccount) : "External"} → {row.toAccount ? accountName(row.toAccount) : "External"}</td><td>{fmt(row.amountUgx)}</td><td>{row.partnerName ? `${row.partnerName}: ` : ""}{row.note || "—"}</td><td>{row.state === "void" ? `Reversed · ${row.voidReason ?? ""}` : "Posted"}</td><td>{can("movements.void") && row.state === "posted" ? <button className="button" type="button" disabled={busy} onClick={() => { const reason = window.prompt("Reason for reversing this movement (at least 5 characters):") ?? ""; if (reason.trim().length >= 5) void reverseMovementWithReview(row._id, reason); }}>Reverse…</button> : "—"}</td></tr>)}</tbody></table></div> : <Empty message="No movements recorded yet." detail="Transfers, deposits, withdrawals, and partner contributions appear here." />}
    </Card>
